CREATE OR REPLACE FUNCTION public.mip_intercept_direct_arc_attachment()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_approved_candidate uuid := nullif(current_setting('app.arc_membership_approval_candidate_id', true), '')::uuid;
begin
  if new.arc_id is distinct from old.arc_id and new.arc_id is not null then
    if v_approved_candidate is not null and exists (select 1 from public.arc_membership_candidates c where c.id = v_approved_candidate and c.article_id = new.id and c.arc_id = new.arc_id and c.state = 'approved') then
      return new;
    end if;
    insert into public.arc_membership_candidates(article_id, arc_id, generation_method, generation_evidence, state)
    values (new.id, new.arc_id, 'direct_attachment_intercept_v1', jsonb_build_object('prior_arc_id', old.arc_id, 'intercepted_at', now()), 'pending')
    on conflict (article_id, arc_id) do update set state = 'pending', invalidated_at = null, generation_evidence = public.arc_membership_candidates.generation_evidence || excluded.generation_evidence;
    new.arc_id := old.arc_id;
    new.arc_assignment_evidence := coalesce(new.arc_assignment_evidence, '{}'::jsonb) || jsonb_build_object('membership_gate', 'staged_pending_score');
  end if;
  return new;
end; $function$

CREATE OR REPLACE FUNCTION public.mip_invalidate_arc_membership_approvals()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_exempt uuid := nullif(current_setting('app.arc_membership_approval_candidate_id', true), '')::uuid;
  v_old_arc uuid := case when tg_op = 'INSERT' then null else old.arc_id end;
  v_new_arc uuid := case when tg_op = 'DELETE' then null else new.arc_id end;
begin
  update public.arc_membership_candidates c set state = 'invalidated', invalidated_at = now()
  where c.state = 'approved' and c.id is distinct from v_exempt and c.arc_id in (v_old_arc, v_new_arc);
  return coalesce(new, old);
end; $function$

CREATE OR REPLACE FUNCTION evidence_pipeline.capture_version()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare before_row jsonb; after_row jsonb; k text; kind text := TG_ARGV[0];
begin
  if TG_OP <> 'INSERT' then before_row := to_jsonb(OLD); end if;
  if TG_OP <> 'DELETE' then after_row := to_jsonb(NEW); end if;
  if kind='temporal_assessment' then
    k := coalesce(after_row->>'key',before_row->>'key');
    if k not like 'temporal.assessment.%' and coalesce(before_row->>'key','') not like 'temporal.assessment.%' then return null; end if;
    if TG_OP='UPDATE' and before_row->>'key' is distinct from after_row->>'key' then
      raise exception 'temporal assessment keys are immutable; insert a new key';
    end if;
  else
    k := coalesce(after_row->>'id',before_row->>'id');
    if TG_OP='UPDATE' and before_row->>'id' is distinct from after_row->>'id' then
      raise exception 'versioned record identity is immutable';
    end if;
  end if;
  -- Embeddings are recomputable, and would dominate retained history size.
  before_row := before_row - 'embedding'; after_row := after_row - 'embedding';
  if TG_OP='UPDATE' and before_row is not distinct from after_row then return null; end if;
  perform pg_advisory_xact_lock(hashtextextended('mip-version:' || kind || ':' || k,0));
  if before_row is not null and not exists(select 1 from evidence_pipeline.record_versions where record_kind=kind and record_key=k) then
    perform evidence_pipeline.append_version(kind,k,'baseline',before_row,'first_observed_before_change');
  end if;
  perform evidence_pipeline.append_version(kind,k,lower(TG_OP),coalesce(after_row,before_row),
    coalesce(nullif(current_setting('mip.change_reason',true),''),'direct_database_change'));
  return null;
end $function$

